CREATE OR REPLACE FUNCTION private.insert_pos_idempotency_processing(p_license_id uuid, p_idempotency_key text, p_operation_type text, p_entity_type text, p_entity_id text, p_request_hash text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row_count integer := 0;
  v_existing_hash text;
  v_existing_status text;
begin
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) = 0 then
    raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode = 'P0001';
  end if;

  insert into public.pos_idempotency_keys (
    license_id, idempotency_key, operation_type, entity_type,
    entity_id, request_hash, status, expires_at
  ) values (
    p_license_id, p_idempotency_key, p_operation_type, p_entity_type,
    p_entity_id, p_request_hash, 'processing', now() + interval '7 days'
  )
  on conflict (license_id, idempotency_key) do nothing;

  get diagnostics v_row_count = row_count;
  if v_row_count > 0 then return true; end if;

  select k.request_hash, k.status
  into v_existing_hash, v_existing_status
  from public.pos_idempotency_keys k
  where k.license_id = p_license_id
    and k.idempotency_key = p_idempotency_key
  for update;

  if p_request_hash is not null
     and v_existing_hash is not null
     and v_existing_hash is distinct from p_request_hash then
    raise exception 'IDEMPOTENCY_CONFLICT' using errcode = 'P0001';
  end if;

  if v_existing_hash is null and p_request_hash is not null
     and v_existing_status = 'processing' then
    update public.pos_idempotency_keys
    set request_hash = p_request_hash
    where license_id = p_license_id
      and idempotency_key = p_idempotency_key
      and request_hash is null;
  end if;

  return false;
end;
$function$

CREATE OR REPLACE FUNCTION private.apply_sale_inventory_effects(p_license_id uuid, p_sale_id text, p_allocations jsonb, p_actor_device_id uuid DEFAULT NULL::uuid, p_actor_staff_user_id uuid DEFAULT NULL::uuid, p_actor_key text DEFAULT NULL::text, p_actor_name text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_response jsonb;
  v_allocation record;
  v_product_id text;
  v_batch_id text;
  v_sale_item_id text;
  v_quantity numeric;
  v_movement_idem text;
  v_movement_id text;
  v_component jsonb;
  v_components jsonb := '[]'::jsonb;
begin
  v_response := private.apply_sale_inventory_effects_direct_rest_inv5(
    p_license_id, p_sale_id, p_allocations,
    p_actor_device_id, p_actor_staff_user_id, p_actor_key, p_actor_name, p_idempotency_key
  );

  for v_allocation in select value as payload, ordinality from jsonb_array_elements(coalesce(p_allocations, '[]'::jsonb)) with ordinality loop
    v_product_id := nullif(v_allocation.payload->>'product_id', '');
    v_batch_id := nullif(v_allocation.payload->>'batch_id', '');
    v_sale_item_id := nullif(v_allocation.payload->>'sale_item_id', '');
    v_quantity := coalesce(nullif(v_allocation.payload->>'quantity', '')::numeric, 0);

    if v_product_id is null or v_sale_item_id is null or v_quantity <= 0 then
      continue;
    end if;

    v_movement_idem := coalesce(p_idempotency_key, p_sale_id) || ':inventory:' || v_sale_item_id || ':' || v_product_id || ':' || coalesce(v_batch_id, 'product') || ':' || v_allocation.ordinality::text;

    select im.id into v_movement_id
    from public.pos_inventory_movements im
    where im.license_id = p_license_id
      and im.idempotency_key = v_movement_idem
    limit 1;

    if v_movement_id is null then
      continue;
    end if;

    v_component := jsonb_build_object(
      'movement_id', v_movement_id,
      'sale_id', p_sale_id,
      'sale_item_id', v_sale_item_id,
      'source', coalesce(v_allocation.payload->>'inventory_source', 'product'),
      'source_product_id', nullif(v_allocation.payload->>'source_product_id', ''),
      'source_product_name', nullif(v_allocation.payload->>'source_product_name', ''),
      'product_id', v_product_id,
      'product_name', nullif(v_allocation.payload->>'product_name', ''),
      'ingredient_id', v_product_id,
      'batch_id', v_batch_id,
      'batch_sku', nullif(v_allocation.payload->>'batch_sku', ''),
      'batch_expiry_date', nullif(v_allocation.payload->>'batch_expiry_date', ''),
      'quantity', v_quantity,
      'unit', nullif(v_allocation.payload->>'component_unit', ''),
      'component_quantity', nullif(v_allocation.payload->>'component_quantity', '')::numeric,
      'modifier_id', nullif(v_allocation.payload->>'modifier_id', ''),
      'modifier_name', nullif(v_allocation.payload->>'modifier_name', ''),
      'component_key', nullif(v_allocation.payload->>'component_key', ''),
      'stock_source', coalesce(v_allocation.payload->>'stock_source', case when v_batch_id is null then 'product' else 'batch' end),
      'unit_cost', nullif(v_allocation.payload->>'unit_cost', '')::numeric,
      'phase', 'rest_inv_5_cloud_restaurant_inventory'
    );

    v_components := v_components || jsonb_build_array(v_component);

    update public.pos_inventory_movements im
    set metadata = coalesce(im.metadata, '{}'::jsonb) || jsonb_build_object(
      'phase', 'rest_inv_5_cloud_restaurant_inventory',
      'inventory_component', v_component,
      'inventory_source', coalesce(v_allocation.payload->>'inventory_source', 'product'),
      'source_product_id', nullif(v_allocation.payload->>'source_product_id', ''),
      'modifier_id', nullif(v_allocation.payload->>'modifier_id', '')
    )
    where im.license_id = p_license_id
      and im.id = v_movement_id;

    update public.pos_sale_items si
    set metadata = coalesce(si.metadata, '{}'::jsonb) || jsonb_build_object(
      'inventoryComponentsUsed', coalesce(si.metadata->'inventoryComponentsUsed', '[]'::jsonb) || jsonb_build_array(v_component),
      'restaurantInventoryPhase', 'rest_inv_5_cloud_restaurant_inventory'
    ),
    server_version = si.server_version + 1
    where si.license_id = p_license_id
      and si.sale_id = p_sale_id
      and si.id = v_sale_item_id;
  end loop;

  update public.pos_sales s
  set metadata = coalesce(s.metadata, '{}'::jsonb) || jsonb_build_object(
    'restaurantInventoryPhase', 'rest_inv_5_cloud_restaurant_inventory',
    'inventoryComponentsUsed', v_components,
    'inventoryComponentsUsedCount', jsonb_array_length(v_components)
  ),
  server_version = s.server_version + 1,
  updated_at = now()
  where s.license_id = p_license_id
    and s.id = p_sale_id;

  perform private.record_pos_sale_audit_event(
    p_license_id,
    p_sale_id,
    'sale.restaurant_inventory_components_audited',
    p_actor_device_id,
    p_actor_staff_user_id,
    p_actor_name,
    jsonb_build_object('sale_id', p_sale_id, 'component_count', jsonb_array_length(v_components), 'components', v_components, 'idempotency_key', p_idempotency_key, 'phase', 'rest_inv_5_cloud_restaurant_inventory')
  );

  return v_response || jsonb_build_object('restaurant_inventory_components', v_components, 'restaurant_inventory_component_count', jsonb_array_length(v_components));
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_cash_permission(p_context jsonb)
